// Texto vindo do node anterior
const text = ($json.output && $json.output.descricao) ? String($json.output.descricao) : "";

// Helper para capturar com regex (retorna "" se não achar)
const get = (re) => {
  const m = text.match(re);
  return m ? m[1].trim() : "";
};

// Alguns rótulos podem ter acento; tratamos ambos
const out = {
  id_os:       get(/id_os:\s*(\d+)/i),
  status:      get(/status:\s*([^,]+)/i),
  id_cliente:  get(/id_cliente:\s*(\d+)/i),
  nome_cliente:get(/nome_cliente\s*:\s*([^,]+?)(?=,\s*assunto\s*:)/i),
  assunto:     get(/assunto\s*:\s*([\s\S]+?)(?=,\s*(?:endereco|endere[cç]o)\s*:)/i),
  endereco:    get(/endere[cç]o:\s*(.*?)(?=,\s*horario:)/i), // pega até "horario:"
  horario:     get(/horario:\s*([^\n,]+)/i),
};

// (Opcional) puxe o número que você já tem em 'tratamento'
try {
  out.numero = $('tratamento').item.json.dados.numero || "";
} catch (e) {
  out.numero = "";
}

return [{ json: out }];

return items.flatMap(item => {
  const raw = item.json.data;

  // Corrige formatação JSON escapada
  const desescapado = raw
    .replace(/\\"/g, '"')
    .replace(/^"|"$/g, '');

  const parsed = JSON.parse(desescapado);
  const registros = parsed.registros || [];

  // Agrupa arquivos por id_oss_chamado
  const agrupado = {};
  for (const os of registros) {
    const id = os.id_oss_chamado;
    if (!agrupado[id]) agrupado[id] = [];
    agrupado[id].push({
      id_arquivo: os.id,
      tipo: os.classificacao_arquivo,
      descricao: os.descricao,
      caminho: os.local_arquivo,
      nome_arquivo: os.nome_arquivo,
      data_envio: os.data_envio
    });
  }

  // Transforma o agrupamento em array de objetos
  const resultado = Object.keys(agrupado).map(id => ({
    json: {
      id_oss_chamado: id,
      arquivos: agrupado[id]
    }
  }));

  console.log('Total de OS agrupadas:', resultado.length);
  return resultado;
});

function isValidado(texto) {
  if (!texto) return false;
  const t = String(texto).toLowerCase();
  const ehValido = /validad[oa]/.test(t);
  const temReprov = /(não|nao)\s+validad|reprov|nao\s+foi\s+validad/.test(t);
  return ehValido && !temReprov;
}

const validados = [];
const naoValidados = [];

for (const item of items) {
  const j = item.json || {};
  const analise = (j.resposta || "").trim();

  const dados = {
    id_os: j.id_os ?? null,
    id_arquivo: j.id_arquivo ?? null,
    nome_arquivo: j.nome_arquivo ?? "",
    descricao: j.descricao ?? "",
    caminho: j.caminho ?? "",
    analise
  };

  if (isValidado(analise)) validados.push(dados);
  else naoValidados.push(dados);
}

return [{
  json: {
    resumo: {
      total: items.length,
      validados: validados.length,
      naoValidados: naoValidados.length
    },
    validados,
    naoValidados
  }
}];

