  return Number.isFinite(n) ? n : null;
}

// --- Entrada ---------------------------------------------------------------

const html = $json.data || "";
// Quebra por </div>, remove tags, decodifica entidades, normaliza espaços/linhas
const text = decodeHtml(
  html
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/div>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
)
  .replace(/[ \t]+\n/g, "\n")
  .replace(/\n[ \t]+/g, "\n")
  .replace(/[ \t]{2,}/g, " ")
  .replace(/\n{2,}/g, "\n")
  .trim();

// --- Extrações -------------------------------------------------------------

const tituloPainel   = pick(/^\s*(Pot[êe]ncia de ONU)\s*$/mi, text) || "Potência de ONU";

const causaUltQueda  = pick(/Causa da .*?queda:\s*([^\n]+)/i, text);
const sinalRx        = toNum(pick(/Sinal\s*Rx:\s*([-\d.,]+)/i, text));
const temperatura    = toNum(pick(/Temperatura:\s*([-\d.,]+)/i, text));
const voltagem       = toNum(pick(/Voltagem:\s*([-\d.,]+)/i, text));
const sinalTx        = toNum(pick(/Sinal\s*Tx:\s*([-\d.,]+)/i, text));
const statusPotencia = pick(/Status\s*pot[êe]ncia:\s*([^\n]+)/i, text);

const fs_p           = pick(/F\/s\/p:\s*([^\n]+)/i, text);
const onuId          = pick(/Onu id:\s*([^\n]+)/i, text);
const controlFlag    = pick(/Control flag:\s*([^\n]+)/i, text);
const runState       = pick(/Run state:\s*([^\n]+)/i, text);
const configState    = pick(/Config state:\s*([^\n]+)/i, text);

const downTime       = pick(/Down time:\s*([^\n]+)/i, text);
const lastDyingGasp  = pick(/Last .*?gasp time:\s*([^\n]+)/i, text);
const onlineDuration = pick(/Online duration:\s*([^\n]+)/i, text);

const macRouter      = pick(/Mac router:\s*([0-9A-Fa-f:]+)/i, text);
const vendorSn       = pick(/Vendor sn:\s*([^\n]*)/i, text) || null;

const txOlt          = toNum(pick(/Tx olt:\s*([-\d.,]+)/i, text));
const rxOlt          = toNum(pick(/Rx olt:\s*([-\d.,]+)/i, text));

// --- Saída (um único item) -------------------------------------------------
return [{
  json: {
    titulo: tituloPainel,
    causa_ultima_queda: causaUltQueda,
    status_potencia: statusPotencia,

    medidas: {
      sinal_rx_dbm: sinalRx,
      sinal_tx_dbm: sinalTx,
      temperatura_c: temperatura,
      voltagem_v: voltagem,
      tx_olt: txOlt,
      rx_olt: rxOlt,
    },

    operacao: {
      fs_p,
      onu_id: onuId,
      control_flag: controlFlag,
      run_state: runState,
      config_state: configState,
      down_time: downTime,
      last_dying_gasp_time: lastDyingGasp,
      online_duration: onlineDuration,
    },

    rede: {
      mac_router: macRouter,
      vendor_sn: vendorSn,
    },

    raw_text: text,     // útil para auditoria/log
  }
}];

